/// Reverses a string.
pub fn reverse(s: &str) -> String {
    s.to_string() // bug: should reverse chars
}

/// Counts vowels (a, e, i, o, u) in a string (case-insensitive).
pub fn count_vowels(s: &str) -> usize {
    s.chars()
        .filter(|c| !"aeiouAEIOU".contains(*c)) // bug: negated — counts non-vowels
        .count()
}

/// Converts a space-separated string to title case.
pub fn title_case(s: &str) -> String {
    s.split_whitespace()
        .map(|word| word.to_lowercase()) // bug: should capitalise first char
        .collect::<Vec<_>>()
        .join(" ")
}

